// QueryAssets queries the assets edge of a Outbound.
func (c *OutboundClient) QueryAssets(_m *Outbound) *MediaAssetQuery {
	query := (&MediaAssetClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(outbound.Table, outbound.FieldID, id),
			sqlgraph.To(mediaasset.Table, mediaasset.FieldID),
			sqlgraph.Edge(sqlgraph.M2M, false, outbound.AssetsTable, outbound.AssetsPrimaryKey...),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

